\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Zum {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kreuzoffizium}}\plain \f1\lang1033\fs20  vgl. Beschreibung von Erik Drigsdahl: http://manuscripts.org.uk/chd.dk/tu\-tor/HSCruce.html. Text entspricht {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kopenhagen, KB, Ms. GkS 1607 4\u176 \'b0}}\plain \f1\lang1033\fs20 , Bl. 14v-15v (Transkription von Erik Drigsdahl: http://manuscripts.org.uk/chd.dk/gks/gks1607_Gui2-HC.html); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Darmstadt, ULB, Hs 4157}}\plain \f1\lang1033\fs20 , Bl. 8v-9v.}

