\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 [{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Philadelphia, Free Library, E M 5:16}}\plain \f1\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 81r-v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Officium beatae Mariae virginis per totum Adventum}}\plain \f1\b\lang1033\fs22  (Fragment)
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs22 >Hymni et uersiculi ut supra de beata Maria uirgine. Ad magnificat antiphona.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Spiritus sanctus in te descendet, Maria, ne timeas}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CAO 5006}}\plain \f1\lang1033\fs22 ). {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Deus, qui de beate marie uirginis utero uerbum tuum, >ut supra in laudibus de cursu Marie}}\plain \f1\i\lang1033\fs22 . De sanctis antiphona.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ecce dominus ueniet et omnes sancti eius cum eo}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CAO 2509}}\plain \f1\lang1033\fs22 ). \plain \f1\i\lang1033\fs22 >Versus.< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ecce apparebit dominus super nubem candidam}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 CAO 2493}}\plain \f1\lang1033\fs22 ).{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  Conscientias nostras, quesumus, domine, uisitando purifica}}\plain \f1\i\lang1033\fs22  ...>Notandum, quia iste due collecte scilicet.< Deus qui de beate Marie >et< Conscientias nostras ... >dicuntur ad omnes horas isto tempore. Ad completorium psalmi ut in cursu beate Marie. Capitulum.< {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ecce uirgo concipiet et pariet filium, et uocabitur nomen eius Emmanuel}}\plain \f1\lang1033\fs22  ({\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cantus-DB 503007}}\plain \f1\lang1033\fs22 ).]
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Text entspricht {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Darmstadt, ULB, Hs 4157, Bl. 77v-78r}}\plain \f1\lang1033\fs20 . }

