\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 [{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Philadelphia, Free Library, E M 5:15}}\plain \f1\lang1033\fs22 , {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 92r-v}}\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Gebet}}\plain \f1\b\lang1033\fs22  zur hl. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Barbara}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs22 >De sancta Barbara antiphona.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ora pro nobis, sancta Barbara, Dioscori filia}}\plain \f1\i\lang1033\fs22 , martir gloriosa ...\plain \f1\lang1033\fs22  (nicht in CAO). \plain \f1\i\lang1033\fs22 >Versu<s.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ora pro nobis, beata uirgo et martir Barbara}}\plain \f1\i\lang1033\fs22 , vt digni efficiamur ...\plain \f1\lang1033\fs22  (nicht in CAO). \plain \f1\i\lang1033\fs22 >Oracio.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Deus, qui beate Barbare uirginis et martiris tue memoriam recolentibus}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22 ]
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Abdruck von Antiphon und Versus nach einer M\u252 \'fcnchener Hs.: Iconographie chr\u233 \'e9tienne: Sainte Barbe, in: Le Beffroi. Art, heraldique, arch\u233 \'e9ologie 4 (1872-1873), S. 5-26, hier S. 14f. Antiphon und Versus auch in: {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M\u252 \'fcnchen, BSB, Clm 28345}}\plain \f1\lang1033\fs20 , Bl. 252r (fl\u228 \'e4misch, Ende 15. Jh.; vgl. G\u252 \'fcnter \plain \f1\scaps\lang1033\fs20 Glauche\plain \f1\lang1033\fs20 ,\plain \f2\lang1033\fs22  \plain \f1\lang1033\fs20 Katalog der lateinischen Handschriften der Bayerischen Staatsbibliothek M\u252 \'fcnchen. Clm 28255-28460, Wiesbaden 1984, S. 134). {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Darmstadt, ULB, Hs 4157}}\plain \f1\lang1033\fs20 , Bl. 29r-30v abweichend.}

