\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 >D<omine, ne in furore tuo arguas me neque in ira tua corripias me}}\plain \f1\i\lang1033\fs22  ...\~\endash \~... Quoniam die ac nocte grauata est super me manus tua, conuersus sum in erumpna\plain \f1\lang1033\fs22  (Ps 6,2-11, Ps 31,2-4)].}

