\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 B\u246 \'f6-Bl/Min/9}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Proprium de sanctis, De s. Helena}}\plain \f1\b\lang1033\fs24  (18.08.)\plain \f1\lang1033\fs24 : \plain \f1\b\lang1033\fs24 In 1. Vesperis\plain \f1\lang1033\fs24 : Ant. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >A<Nn}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [ua beatae Helenae sollem]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 nia}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  [votivis laudibus excipiamus}}\plain \f1\lang1033\fs24  ut] \plain \f1\i\lang1033\fs24 eius meritis et in\plain \f1\lang1033\fs24 [tercessione a malis nostris sub]\plain \f1\i\lang1033\fs24 leuemur \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C-DB 206181}}\plain \f1\lang1033\fs24 ), {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >O<}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  [glorisoa regina}}\plain \f1\lang1033\fs24  ... (?)] // (Verso) \plain \f1\b\lang1033\fs24 In 1. Nocturno\plain \f1\lang1033\fs24 : Ant. [1. Jucundemur, adest enim / Helen]\plain \f1\i\lang1033\fs24 e sollempnitas, / quam\plain \f1\lang1033\fs24  [de stirpe generosa / produxit gentil]\plain \f1\i\lang1033\fs24 itas, / sed adduxit ve\plain \f1\lang1033\fs24 [ra fides / hanc ad Christi semitas.], Ps. \plain \f1\i\lang1033\fs24 Domine, dominus\plain \f1\lang1033\fs24  [noster quam ...], Ant. [2. Haec Silvestri cum vidisset / glo]\plain \f1\i\lang1033\fs24 riosi precibus, / inuocan\plain \f1\lang1033\fs24 [tis nomen Christi, / signa cum virtutibus, / ...].
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Die Ges\u228 \'e4nge zur 1. Vesper \u8222 \'84Annua beatae Helenae\ldblquote  und \u8222 \'84O gloriosa regina\ldblquote  auch in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Trier, BA, Ms. Nr. 480}}\plain \f1\lang1033\fs24 , 247\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , vgl. \plain \f1\scaps\lang1033\fs24 Brink\plain \f1\lang1033\fs24 , Historiae Trevirenses (s. o.), Appendix, S. 102, dort jedoch nicht das (wohl j\u252 \'fcngere?) Reimoffizium zur 1. Nokturn \u8222 \'84Jucundemur, adest enim\rdblquote . Ein Offizium zum Helena-Fest mit der Ant. \u8222 \'84Annua beatae Helenae\ldblquote  am Beginn ist in verschiedenen Quellen aus Trier nachgewiesen, vgl. \plain \f1\scaps\lang1033\fs24 Brink\plain \f1\lang1033\fs24 , ebd., Bd. 1, S. 239-241, 246 u. \u246 \'f6., Bd. 2, S. 93, hier das Offizium \u8222 \'84Jucundemur, adest enim\ldblquote , S. 238, Anm. 443 nur als weiteres Offizium zum Fest erw\u228 \'e4hnt. Vgl. auch Adalbert \plain \f1\scaps\lang1033\fs24 Kurzeja\plain \f1\lang1033\fs24 , Der \u228 \'e4lteste Liber Ordinarius der Trierer Domkirche: London, Brit. Mus., Harley 2958, Anfang 14. Jh. Ein Beitrag zur Liturgiegeschichte der deutschen Ortskirchen (Liturgiewissenschaftliche Quellen und Forschungen 52), M\u252 \'fcnster 1970 S. 539, ebd. S. 196f. u. \u246 \'f6. zur Verehrung der Hl. Helena als Patronin in Trier. Zu zwei weiteren Cuttings mit diesem Offiziumsbeginn (evtl. ebenfalls aus Trier?) vgl. {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 B\u246 \'f6-Bl/Min/61-75 und B\u246 \'f6-Bl/Min/78.}}
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zum Reimoffizium zur 1. Nokturn \u8222 \'84Jucundemur, adest enim\ldblquote  vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 18, Nr. 33}}\plain \f1\lang1033\fs24  (Teiled. nach {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paris, Bibl. Mazarine, ms. 372}}\plain \f1\lang1033\fs24 , ca. 1470-80).}

