\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 De sancta Anna (26.07.). Ad Matutinum\plain \f1\lang1033\fs24 , Reimoffizium, (Recto), \plain \f1\b\lang1033\fs24 In 1. Nocturno\plain \f1\lang1033\fs24 . [Ant. Ea quidem tempestate / praesul erat Isachar, / \plain \f1\lang1033\fs24\cf1 qui Io]\plain \f1\i\lang1033\fs24\cf1 achim infecundi / \plain \f1\i\lang1033\fs24 refu\plain \f1\lang1033\fs24 [tabat munera. ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C-DB 201448}}\plain \f1\lang1033\fs24 )], [Ant. Ex]\plain \f1\i\lang1033\fs24 probrabat et dice\plain \f1\lang1033\fs24 [bat / hunc valde praesumere / \plain \f1\lang1033\fs24\cf1 qui fecundis infecundus / se captabat sistere. \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C-DB 201729}}\plain \f1\lang1033\fs24 )\plain \f1\lang1033\fs24\cf1 ] //\plain \f1\lang1033\fs24  (Verso) \plain \f1\i\lang1033\fs24 >F<E\plain \f1\lang1033\fs24 [...], evtl. Ant. in 2. Vesperis, Ad Magnificat: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Felix Anna / quedam matrona}}\plain \f1\lang1033\fs24  / legitima beato Ioachim ... ({\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C-DB 201801}}\plain \f1\lang1033\fs24 ).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 Zugeh\u246 \'f6rig zum weit verbreiteten Reimoffizium \u8222 \'84Anna sancta, de qua nata fuit mater domini ...\ldblquote  , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 AH 25, Nr. 18}}\plain \f1\lang1033\fs24\cf1 , hier S. 52 und 54.}

