\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Lit.:
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 - Sch\u228 \'e4tze der ehemaligen Bibliothek des B\u246 \'f6rsenvereins der Deutschen Buchh\u228 \'e4ndler zu Leipzig, bearb. von Fritz \plain \f1\scaps\lang1033\fs24 Funke\plain \f1\lang1033\fs24 , Martha \plain \f1\scaps\lang1033\fs24 Debes\plain \f1\lang1033\fs24  u. a. Mit einem Geleitw. von Heinrich \plain \f1\scaps\lang1033\fs24 Becker\plain \f1\lang1033\fs24  (Neujahrsgabe der Deutschen B\u252 \'fccherei 1962), Leipzig 1962, hier S. 24f. mit Abb. von 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , mit Angabe: \u8222 \'84Ende 13. Jh., vermutlich rheinisch-s\u252 \'fcddeutscher Herkunft\ldblquote .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red0\green176\blue80;}

