\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 B\u246 \'f6-Bl/Min/83}}\plain \f1\lang1033\fs24  (Recto) \plain \f1\b\lang1033\fs24 In Sabbato sancto\plain \f1\lang1033\fs24 , [Beginn fehlt: ... \plain \f1\b\lang1033\fs24 Schluss des Exsultet\plain \f1\lang1033\fs24 : Exsultet iam angelica turba caelorum ... Oramus ergo te, domine, ut cereus iste in hono]\plain \f1\i\lang1033\fs24 rem nominis tui conse\plain \f1\lang1033\fs24 [cratus ad noctis huius caligi]\plain \f1\i\lang1033\fs24 nem destruendam inde\plain \f1\lang1033\fs24 [ficiens perseveret in odorem su]\plain \f1\i\lang1033\fs24 auitatis acceptus super\plain \f1\lang1033\fs24 [nis luminaribus misceatur.] \plain \f1\i\lang1033\fs24 Flammas eius matuti\plain \f1\lang1033\fs24 [nus Lucifer inveniat. Ille in] \plain \f1\i\lang1033\fs24 quam Lucifer qui nescit\plain \f1\lang1033\fs24  [occasum ille qui regressus ab] \plain \f1\i\lang1033\fs24 inferis humano generi\plain \f1\lang1033\fs24  (Verso) [serenus illuxit. Praecamur igitur te domine ut nos famulos tuos omnem clerum et devotissimum populum una cum papa nostro et gloriosissimo rege nostro N ejusque conjuge et nobilissima prole quiete temporum concessa in his paschalibus gaudiis conservare dign]\plain \f1\i\lang1033\fs24 eris. Per dominum nostrum Ihesum Xp\plain \f1\lang1033\fs24 [istum filium tuum qui tecum vivit et regnat deus] \plain \f1\i\lang1033\fs24 in unitate spiritus sancti deus per omni\plain \f1\lang1033\fs24 [a secula seculorum amen].\plain \f1\lang1033\fs20  \plain \f1\b\lang1033\fs24 Dominica Resurrectionis\plain \f1\lang1033\fs24 : Intr.{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >R<es}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [urrexi et adhuc tecum] }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 su}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [m}}\plain \f1\lang1033\fs24 , alleluia, po]\plain \f1\i\lang1033\fs24 su\plain \f1\lang1033\fs24 [isti super me manum tuam, al]\plain \f1\i\lang1033\fs24 leluya, mirabilis\plain \f1\lang1033\fs24  [facta est scientia tua, alleluia, alleluia ({\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C-DB g01007}}\plain \f1\lang1033\fs24 )}

